param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$OutputDirectory,[int]$TextScale=100,[int]$Width=1000,[int]$Height=650,[switch]$SkipDropdown,[switch]$MissingEngine)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;public static class SettingsNative{[DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]public static extern IntPtr GetForegroundWindow();[DllImport("user32.dll")]public static extern void keybd_event(byte k,byte s,uint f,UIntPtr i);[DllImport("user32.dll")]public static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int z,uint f);}'
$output=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path -LiteralPath $output){throw 'Fresh own output required'};[IO.Directory]::CreateDirectory($output)|Out-Null
$data=Join-Path $output 'isolated-data';$statePath=Join-Path $data 'window-state.json';$process=$null;$checks=0
function State{try{$r=[IO.StreamReader]::new([IO.File]::Open($statePath,'Open','Read',([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete)));try{return $r.ReadToEnd()|ConvertFrom-Json}finally{$r.Dispose()}}catch [IO.IOException]{return $null}}
function Await([scriptblock]$test,[string]$name){$until=[DateTime]::UtcNow.AddSeconds(35);do{if(&$test){return};if($process.HasExited){throw ('EXIT '+$name)};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow -lt $until);$detail=@{};foreach($controlId in @('ManagePreferenceCache','ManagePreferenceThumbnail','ManageFormScroll','ManageSavePreferences')){$control=Find $controlId;if($control){$detail[$controlId]=@{enabled=$control.Current.IsEnabled;offscreen=$control.Current.IsOffscreen;rect=$control.Current.BoundingRectangle.ToString()};$pattern=$null;if($control.TryGetCurrentPattern([Windows.Automation.ScrollPattern]::Pattern,[ref]$pattern)){$detail[$controlId].scroll=$pattern.Current.VerticalScrollPercent;$detail[$controlId].scrollable=$pattern.Current.VerticallyScrollable}}};@{name=$name;state=State;controls=$detail}|ConvertTo-Json -Depth 15|Set-Content -LiteralPath (Join-Path $output 'timeout-settings.json');throw ('TIMEOUT '+$name)}
function Check([bool]$ok,[string]$name){if(-not $ok){throw ('SETTINGS_UI_FAIL '+$name)};$script:checks++}
function Find([string]$id){return $script:root.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::AutomationIdProperty,$id))}
function Reach([string]$id){$candidate=Find $id;if($candidate -and $candidate.Current.IsEnabled){try{$candidate.SetFocus()}catch{}};Await {$e=Find $id;if(-not $e -or -not $e.Current.IsEnabled){return $false};$b=$e.Current.BoundingRectangle;$w=$root.Current.BoundingRectangle;$scroll=Find 'ManageFormScroll';if($scroll -and $id -notlike 'Nav*'){$view=$scroll.Current.BoundingRectangle;$sp=$scroll.GetCurrentPattern([Windows.Automation.ScrollPattern]::Pattern);if($sp.Current.VerticallyScrollable -and ($b.Height -lt 26 -or $b.Top -lt $view.Top -or $b.Bottom -gt [Math]::Min($view.Bottom,$w.Bottom-48))){$dir=if($b.Height -gt 0 -and $b.Top -lt $view.Top){[Windows.Automation.ScrollAmount]::SmallDecrement}else{[Windows.Automation.ScrollAmount]::SmallIncrement};$sp.Scroll([Windows.Automation.ScrollAmount]::NoAmount,$dir);return $false}};return -not $e.Current.IsOffscreen -and $b.Height -ge 26 -and $b.Top -ge $w.Top -and $b.Bottom -le $w.Bottom} $id}
function Click([string]$id){Reach $id;(Find $id).GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke();$script:checks++}
function Capture([string]$name){Click 'ThemeLight';Await {$s=State;return $s.revision -eq $s.captureRevision} ('capture '+$name);$s=State;Copy-Item -LiteralPath (Join-Path $data $s.captures[-1]) -Destination (Join-Path $output ($name+'.png'))}
try{
 $start=[Diagnostics.ProcessStartInfo]::new([IO.Path]::GetFullPath($Executable));$start.UseShellExecute=$false;$start.WindowStyle='Hidden';$start.Arguments='--data-dir "'+$data+'" --diagnostics --capture --text-scale '+$TextScale
 $process=[Diagnostics.Process]::Start($start);Await {(State).ready} 'ready';$script:root=[Windows.Automation.AutomationElement]::FromHandle([IntPtr][long](State).hwnd);[SettingsNative]::SetWindowPos([IntPtr][long](State).hwnd,[IntPtr]::Zero,0,0,$Width,$Height,0x14)|Out-Null
 Check ($null -ne (Find 'NavSettings')) 'direct settings button'
 Click 'NavSettings';Await {(State).page -eq 'Settings'} 'settings'
 Check (-not (State).engineStarted) 'appearance does not start engine'
 Click 'ThemeDark';Await {(State).actualTheme -eq 'Dark'} 'dark appearance'
 Click 'MaterialToggle';Await {-not (State).material.requested -and (State).material.nativeLayers -eq 0} 'solid preference'
 (Find 'ReduceMotion').GetCurrentPattern([Windows.Automation.TogglePattern]::Pattern).Toggle();Await {(State).workspace.reducedMotion} 'reduce motion'
 Click 'MaterialToggle';Click 'ThemeLight'
 Click 'SettingsOpenLibrary';if($MissingEngine){Await {(State).engine.state -eq '连接失败'} 'visible connection failure';Check ((State).workspace.management.feedback -like '*缺少引擎*') 'settings shows connection error';Click 'ThemeDark';Check ((State).actualTheme -eq 'Dark') 'appearance survives connection failure';$process.CloseMainWindow()|Out-Null;Check ($process.WaitForExit(30000)) 'safe failed-engine close';@{result='passed';count=$checks;syntheticOnly=$true;networkUsed=$false}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $output 'settings-failure-report.json');return};Await {(State).engine.connected -and $null -ne (Find 'ManagePreferenceDensity')} 'explicit local service and settings stay open'
 Check (-not (State).engine.galleryOpened -and -not (State).engine.startupCatalogQueried) 'Civitai settings do not require gallery startup'
 Check ((State).page -eq 'Settings') 'connection preserves settings destination'
 if(-not $SkipDropdown){ $choice=Find 'ManagePreferenceDensity';Reach 'ManagePreferenceDensity';$expand=$choice.GetCurrentPattern([Windows.Automation.ExpandCollapsePattern]::Pattern);[SettingsNative]::SetForegroundWindow([IntPtr][long](State).hwnd)|Out-Null;Await {[SettingsNative]::GetForegroundWindow() -eq [IntPtr][long](State).hwnd} 'own foreground';$choice.SetFocus();[SettingsNative]::keybd_event(0x73,0,0,[UIntPtr]::Zero);[SettingsNative]::keybd_event(0x73,0,2,[UIntPtr]::Zero);Await {$expand.Current.ExpandCollapseState -eq [Windows.Automation.ExpandCollapseState]::Expanded} 'F4 opens native dropdown';Check $true 'F4 keyboard open';[SettingsNative]::keybd_event(0x1B,0,0,[UIntPtr]::Zero);[SettingsNative]::keybd_event(0x1B,0,2,[UIntPtr]::Zero);Await {$expand.Current.ExpandCollapseState -eq [Windows.Automation.ExpandCollapseState]::Collapsed} 'Escape closes';Check $true 'Escape keyboard close';$expand.Expand();Await {$expand.Current.ExpandCollapseState -eq [Windows.Automation.ExpandCollapseState]::Expanded} 'native dropdown expands'
 $item=$root.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::NameProperty,'紧凑'));Check ($null -ne $item) 'native dropdown option accessible';$item.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();$expand.Collapse();};Click 'ManageSavePreferences';Await {-not (State).workspace.management.writing} 'preferences saved'
 Capture 'settings-appearance'
 Reach 'ManagePreferenceCache';(Find 'ManagePreferenceCache').GetCurrentPattern([Windows.Automation.RangeValuePattern]::Pattern).SetValue(128);Click 'ManageSavePreferences';Await {-not (State).workspace.management.writing} 'cache saved'
 Click 'NavJobs';Check ($null -eq (Find 'ManagePreferenceCache')) 'tasks no longer contain preferences'
 Click 'NavModels';Check ($null -eq (Find 'ManageApiToken')) 'models no longer contain token field';Click 'NavSettings';Await {(State).page -eq 'Settings'} 'global settings remains directly available from empty models'
 Reach 'ManageApiToken';(Find 'ManageApiToken').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).SetValue('synthetic-local-token-0123456789');Click 'ManageSaveCredential';Await {(State).workspace.management.credentialConfigured -and -not (State).workspace.management.writing} 'explicit synthetic session credential'
 Click 'ManageClearCredential';Await {-not (State).workspace.management.credentialConfigured -and -not (State).workspace.management.writing} 'clear synthetic credential'
 Reach 'ManagePreferenceCache';Check ((Find 'ManagePreferenceCache').GetCurrentPattern([Windows.Automation.RangeValuePattern]::Pattern).Current.Value -eq 128) 'settings quota persisted'
 Click 'SettingsStorage';Await {(State).page -eq 'Storage'} 'direct data tools'
 Click 'ClosePreview';Check ($process.WaitForExit(30000) -and $process.ExitCode -eq 0) 'safe close'
 @{result='passed';count=$checks;textScale=$TextScale;width=$Width;height=$Height;syntheticOnly=$true;networkUsed=$false;captureScope='own XAML only; not compositor proof'}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $output 'settings-window-report.json')
 Write-Output ('SETTINGS_WINDOW_PASSED '+$checks)
}finally{if($process -and -not $process.HasExited){$process.CloseMainWindow()|Out-Null;$process.WaitForExit(30000)|Out-Null}}
